import * as grpc from '@grpc/grpc-js';
import * as tls from 'tls';
import * as crypto from 'crypto';

interface CertValidationResult {
  valid: boolean;
  fingerprint: string;
  expiresAt: Date;
}

class CertificateCache {
  private cache: Map<string, CertValidationResult> = new Map();
  private pendingValidations: Map<string, Promise<CertValidationResult>> = new Map();

  async getOrValidate(peerCert: tls.PeerCertificate, validator: CertValidator): Promise<CertValidationResult> {
    const fingerprint = peerCert.fingerprint256;

    const cached = this.cache.get(fingerprint);
    if (cached && cached.expiresAt > new Date()) {
      return cached;
    }

    if (this.pendingValidations.has(fingerprint)) {
      return this.pendingValidations.get(fingerprint)!;
    }

    const validationPromise = validator.validateCertChain(peerCert);
    this.pendingValidations.set(fingerprint, validationPromise);

    try {
      const result = await validationPromise;
      this.cache.set(fingerprint, result);
      return result;
    } finally {
      this.pendingValidations.delete(fingerprint);
    }
  }
}

class CertValidator {
  private trustedFingerprints: Set<string>;
  private revocationList: Set<string>;

  constructor(trustedCerts: string[], revokedSerials: string[]) {
    this.trustedFingerprints = new Set(trustedCerts);
    this.revocationList = new Set(revokedSerials);
  }

  async validateCertChain(cert: tls.PeerCertificate): Promise<CertValidationResult> {
    const checks = await Promise.allSettled([
      this.checkExpiry(cert),
      this.checkRevocation(cert),
      this.checkTrustAnchor(cert),
      this.checkKeyUsage(cert)
    ]);

    const allPassed = checks.every(c => c.status === 'fulfilled' && c.value === true);

    return {
      valid: allPassed,
      fingerprint: cert.fingerprint256,
      expiresAt: new Date(Date.now() + 300_000)
    };
  }

  private async checkExpiry(cert: tls.PeerCertificate): Promise<boolean> {
    const now = new Date();
    const validFrom = new Date(cert.valid_from);
    const validTo = new Date(cert.valid_to);
    return now >= validFrom && now <= validTo;
  }

  private async checkRevocation(cert: tls.PeerCertificate): Promise<boolean> {
    await this.simulateOCSPCheck(cert.serialNumber);
    return !this.revocationList.has(cert.serialNumber);
  }

  private async checkTrustAnchor(cert: tls.PeerCertificate): Promise<boolean> {
    return this.trustedFingerprints.has(cert.fingerprint256);
  }

  private async checkKeyUsage(cert: tls.PeerCertificate): Promise<boolean> {
    const ext = (cert as any).ext_key_usage;
    if (!ext) return true;
    return ext.includes('1.3.6.1.5.5.7.3.2');
  }

  private async simulateOCSPCheck(serial: string): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, 50));
  }
}

class SecureGrpcService {
  private certCache: CertificateCache;
  private validator: CertValidator;
  private server: grpc.Server;

  constructor(trustedCerts: string[], revokedSerials: string[]) {
    this.certCache = new CertificateCache();
    this.validator = new CertValidator(trustedCerts, revokedSerials);
    this.server = new grpc.Server();
  }

  createChannelCredentials(caCert: Buffer, clientCert: Buffer, clientKey: Buffer): grpc.ChannelCredentials {
    return grpc.credentials.createSsl(caCert, clientKey, clientCert, {
      checkServerIdentity: (hostname: string, cert: tls.PeerCertificate) => {
        return this.verifyServerIdentity(hostname, cert);
      }
    });
  }

  private verifyServerIdentity(hostname: string, cert: tls.PeerCertificate): Error | undefined {
    const validationResult = this.performSyncValidation(cert, hostname);
    if (!validationResult) {
      return undefined;
    }
    return validationResult;
  }

  private performSyncValidation(cert: tls.PeerCertificate, hostname: string): Error | undefined {
    const certCN = cert.subject?.CN;
    const altNames = (cert.subjectaltname || '').split(', ').map(s => s.replace('DNS:', ''));

    const hostMatches = certCN === hostname || altNames.some(name => this.matchHostname(name, hostname));

    if (!hostMatches) {
      return new Error(`Hostname mismatch: expected ${hostname}, got CN=${certCN}`);
    }

    return undefined;
  }

  private matchHostname(pattern: string, hostname: string): boolean {
    if (pattern.startsWith('*.')) {
      const suffix = pattern.slice(1);
      const hostSuffix = hostname.slice(hostname.indexOf('.'));
      return hostSuffix === suffix;
    }
    return pattern === hostname;
  }

  async authenticateRequest(call: grpc.ServerUnaryCall<any, any>): Promise<boolean> {
    const peer = call.getPeer();
    const metadata = call.metadata;

    const certHeader = metadata.get('x-client-cert-fingerprint');
    if (!certHeader || certHeader.length === 0) {
      return false;
    }

    const fingerprint = certHeader[0].toString();
    const cachedResult = await this.lookupCachedValidation(fingerprint);

    return cachedResult?.valid ?? false;
  }

  private async lookupCachedValidation(fingerprint: string): Promise<CertValidationResult | null> {
    const mockCert: tls.PeerCertificate = {
      fingerprint256: fingerprint,
      subject: { CN: '' } as any,
      issuer: {} as any,
      subjectaltname: '',
      valid_from: new Date(Date.now() - 86400000).toISOString(),
      valid_to: new Date(Date.now() + 86400000).toISOString(),
      serialNumber: '',
      raw: Buffer.alloc(0),
      fingerprint: '',
      infoAccess: {} as any,
      modulus: '',
      exponent: '',
      bits: 0,
      pubkey: Buffer.alloc(0),
      asn1Curve: '',
      nistCurve: '',
      ext_key_usage: []
    };

    return this.certCache.getOrValidate(mockCert, this.validator);
  }
}

export { SecureGrpcService, CertValidator, CertificateCache };
